#include "stdlib/blas/base/strsv.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/ndarray/base/assert/is_row_major.h"

/**
* Solves one of the systems of equations `A*X = b` or `A^T*X = b` using alternative indexing semantics, where `b` and `X` are `N` element vectors and `A` is an `N` by `N` unit, or non-unit, upper or lower triangular matrix.
*
* @param uplo      specifies whether `A` is an upper or lower triangular matrix
* @param trans     specifies whether `A` should be transposed, conjugate-transposed, or not transposed
* @param diag      specifies whether `A` has a unit diagonal
* @param N         number of elements along each dimension of `A`
* @param A         input matrix
* @param strideA1  stride of the first dimension of `A`
* @param strideA2  stride of the second dimension of `A`
* @param offsetA   starting index for `A`
* @param X         input vector
* @param strideX   `X` stride length
* @param offsetX   starting index for `X`
* @return          output value
*/
void API_SUFFIX(c_strsv_ndarray)( const CBLAS_UPLO uplo, const CBLAS_TRANSPOSE trans, const CBLAS_DIAG diag, const CBLAS_INT N, const float *A, const CBLAS_INT strideA1, const CBLAS_INT strideA2, const CBLAS_INT offsetA, float *X, const CBLAS_INT strideX, const CBLAS_INT offsetX ) {
	CBLAS_INT nonunit;
	CBLAS_INT isrm;
	CBLAS_INT ix1;
	CBLAS_INT ix0;
	CBLAS_INT sa0;
	CBLAS_INT sa1;
	CBLAS_INT i0;
	CBLAS_INT i1;
	CBLAS_INT oa;
	CBLAS_INT ox;
	float tmp;

	// Note on variable naming convention: sa#, ix#, i# where # corresponds to the loop number, with `0` being the innermost loop...

	int64_t strides[] = { strideA1, strideA2 };
	isrm = stdlib_ndarray_is_row_major( 2, strides );
	nonunit = ( diag == CblasNonUnit );

	if ( isrm ) {
		// For row-major matrices, the last dimension has the fastest changing index...
		sa0 = strideA2; // stride for innermost loop
		sa1 = strideA1; // stride for outermost loop
	} else { // isColMajor
		// For column-major matrices, the first dimension has the fastest changing index...
		sa0 = strideA1; // stride for innermost loop
		sa1 = strideA2; // stride for outermost loop
	}
	ox = offsetX;

	if (
		( !isrm && trans == CblasNoTrans && uplo == CblasUpper ) ||
		( isrm && trans != CblasNoTrans && uplo == CblasLower )
	) {
		ix1 = ox + ( ( N - 1 ) * strideX );
		for ( i1 = N-1; i1 >= 0; i1-- ) {
			if ( X[ ix1 ] != 0.0f ) {
				oa = offsetA + (sa1*i1);
				if ( nonunit ) {
					X[ ix1 ] /= A[ oa+(sa0*i1) ];
				}
				tmp = X[ ix1 ];
				ix0 = ix1;
				for ( i0 = i1-1; i0 >= 0; i0-- ) {
					ix0 -= strideX;
					X[ ix0 ] -= tmp * A[ oa+(sa0*i0) ];
				}
			}
			ix1 -= strideX;
		}
		return;
	}
	if (
		( !isrm && trans == CblasNoTrans && uplo == CblasLower ) ||
		( isrm && trans != CblasNoTrans && uplo == CblasUpper )
	) {
		ix1 = ox;
		for ( i1 = 0; i1 < N; i1++ ) {
			if ( X[ ix1 ] != 0.0f ) {
				oa = offsetA + (sa1*i1);
				if ( nonunit ) {
					X[ ix1 ] /= A[ oa+(sa0*i1) ];
				}
				tmp = X[ ix1 ];
				ix0 = ix1;
				for ( i0 = i1+1; i0 < N; i0++ ) {
					ix0 += strideX;
					X[ ix0 ] -= tmp * A[ oa+(sa0*i0) ];
				}
			}
			ix1 += strideX;
		}
		return;
	}
	if (
		( !isrm && trans != CblasNoTrans && uplo == CblasUpper ) ||
		( isrm && trans == CblasNoTrans && uplo == CblasLower )
	) {
		ix1 = ox;
		for ( i1 = 0; i1 < N; i1++ ) {
			tmp = X[ ix1 ];
			oa = offsetA + (sa1*i1);
			ix0 = ox;
			for ( i0 = 0; i0 <= i1-1; i0++ ) {
				tmp -= X[ ix0 ] * A[ oa+(sa0*i0) ];
				ix0 += strideX;
			}
			if ( nonunit ) {
				tmp /= A[ oa+(sa0*i1) ];
			}
			X[ ix1 ] = tmp;
			ix1 += strideX;
		}
		return;
	}
	// ( !isrm && trans != CblasNoTrans && uplo == CblasLower ) || ( isrm && trans == CblasNoTrans && uplo == CblasUpper )
	ox += ( N - 1 ) * strideX;
	ix1 = ox;
	for ( i1 = N-1; i1 >= 0; i1-- ) {
		tmp = X[ ix1 ];
		oa = offsetA + (sa1*i1);
		ix0 = ox;
		for ( i0 = N-1; i0 > i1; i0-- ) {
			tmp -= X[ ix0 ] * A[ oa+(sa0*i0) ];
			ix0 -= strideX;
		}
		if ( nonunit ) {
			tmp /= A[ oa+(sa0*i1) ];
		}
		X[ ix1 ] = tmp;
		ix1 -= strideX;
	}
	return;
}
